// Recibe el símbolo y crea una petición por cada temporalidad.
const bruto = $input.first()?.json?.symbol;
let symbol = String(bruto ?? '').trim().toUpperCase();

// Si lo ejecutas a mano en el editor y llega sin símbolo (por ejemplo, por el disparador del orquestador),
// usa uno de prueba. Cuando lo llama el orquestador esto no se aplica y el error se mantiene.
if (!symbol && $execution.mode === 'test') {
  symbol = 'BTC/USD';
}

if (!symbol) {
  throw new Error('Falta el campo "symbol" (ejemplos: BTC/USD, EUR/USD, AAPL).');
}

return ['5min', '15min', '1day'].map(interval => ({ json: { symbol, interval } }));

// Une las 3 respuestas de TwelveData en un solo objeto de velas y valida los datos.
const MIN_VELAS = 200;       // el libro usa la media simple de 200 periodos en diario, 15 y 5 minutos
const MAX_EDAD_5M_MIN = 15;  // aviso si la última vela de 5 min es más vieja que esto

const peticiones = $('Preparar peticiones').all();
const respuestas = $input.all();
const destino = { '5min': 'candles5m', '15min': 'candles15m', '1day': 'candles1d' };

function aISO(texto) {
  if (!texto) return null;
  const t = String(texto).trim();
  const iso = t.length === 10 ? `${t}T00:00:00Z` : `${t.replace(' ', 'T')}Z`;
  const fecha = new Date(iso);
  return Number.isNaN(fecha.getTime()) ? null : fecha.toISOString();
}

function parsear(respuesta, intervalo) {
  const j = respuesta?.json ?? {};

  if (j.error) {
    const msg = typeof j.error === 'string' ? j.error : (j.error.message || JSON.stringify(j.error));
    return { error: `${intervalo}: falló la conexión (${msg})` };
  }
  if (j.status === 'error' || Number(j.code) >= 400) {
    const detalle = `${j.code ?? ''} ${j.message ?? ''}`.replace(/\s+/g, ' ').trim();
    return { error: `${intervalo}: TwelveData respondió ${detalle}` };
  }
  if (!Array.isArray(j.values) || j.values.length === 0) {
    return { error: `${intervalo}: la respuesta no trae velas` };
  }

  const velas = j.values
    .map(v => ({
      time: aISO(v.datetime),
      open: Number(v.open),
      high: Number(v.high),
      low: Number(v.low),
      close: Number(v.close),
      volume: Number(v.volume || 0)
    }))
    .filter(c => c.time && [c.open, c.high, c.low, c.close].every(Number.isFinite) && c.high >= c.low)
    .sort((a, b) => a.time.localeCompare(b.time));

  if (velas.length === 0) {
    return { error: `${intervalo}: ninguna vela pasó la validación` };
  }
  return { velas };
}

const resultado = {
  ok: false,
  ticker: peticiones[0]?.json.symbol ?? null,
  candles5m: [],
  candles15m: [],
  candles1d: [],
  errors: [],
  warnings: [],
  fetchedAt: new Date().toISOString()
};

peticiones.forEach((p, i) => {
  const intervalo = p.json.interval;
  const r = parsear(respuestas[i], intervalo);
  if (r.error) {
    resultado.errors.push(r.error);
    return;
  }
  resultado[destino[intervalo]] = r.velas;
  if (r.velas.length < MIN_VELAS) {
    resultado.warnings.push(`${intervalo}: solo ${r.velas.length} velas (se recomiendan ${MIN_VELAS}+ para la media de 200)`);
  }
});

resultado.ok = resultado.errors.length === 0;

const ultima = resultado.candles5m.at(-1);
if (ultima) {
  resultado.lastPrice = ultima.close;
  resultado.lastCandleTime = ultima.time;
  const edadMin = (Date.now() - new Date(ultima.time).getTime()) / 60000;
  resultado.lastCandleAgeMin = Math.round(edadMin * 10) / 10;
  if (edadMin > MAX_EDAD_5M_MIN) {
    resultado.warnings.push(`la última vela de 5 min tiene ${resultado.lastCandleAgeMin} min de antigüedad (¿mercado cerrado o datos atrasados?)`);
  }
}

return [{ json: resultado }];
